template.script:
(function () {
  window.AUCTION_IS_MYSTERY = false;
  window.AUCTION_MYSTERY_REVEALED = false;
  window.AUCTION_MYSTERY_AWAITING_REVEAL = false;
  window.AUCTION_MYSTERY_SOLD_INFO = null;

  function acMysteryFlag() {
    return document.body.getAttribute('data-is-mystery') === '1';
  }

  function acMysterySetRevealed(revealed) {
    window.AUCTION_MYSTERY_REVEALED = !!revealed;
    if (revealed) document.body.setAttribute('data-mystery-revealed', '1');
    else document.body.removeAttribute('data-mystery-revealed');
  }

  function acMysteryNextButtons() {
    return document.querySelectorAll(
      '.next-player-btn, .lm-btn-next, .sw-btn-next, .hud-next-btn, .cr-btn-next, .pt-next-btn, button[onclick*="changeImage"]'
    );
  }

  function acMysteryActionButtons() {
    return document.querySelectorAll(
      'button[onclick*="openSellModal"], button[onclick*="setPlayerUnsold"],' +
      '.sell, .pt-btn-sell, .pt-btn-unsold, .hud-btn-sell, .hud-btn-unsold,' +
      '.lm-btn-sell, .lm-btn-unsold, .sw-btn-sell, .sw-btn-unsold,' +
      '.cr-btn-sell, .cr-btn-unsold'
    );
  }

  function acMysteryHideActionButtons() {
    var btns = acMysteryActionButtons();
    for (var i = 0; i < btns.length; i++) btns[i].classList.add('ac-mystery-action-hidden');
  }

  function acMysteryShowActionButtons() {
    var btns = document.querySelectorAll('.ac-mystery-action-hidden');
    for (var i = 0; i < btns.length; i++) btns[i].classList.remove('ac-mystery-action-hidden');
  }

  function acMysteryRemoveSoldStamp() {
    var stamps = document.querySelectorAll('.ac-mystery-sold-stamp');
    for (var i = 0; i < stamps.length; i++) {
      if (stamps[i].parentNode) stamps[i].parentNode.removeChild(stamps[i]);
    }
  }

  function acMysteryPhotoWrap() {
    var img = document.getElementById('loadImage');
    return img ? img.parentElement : null;
  }

  var AC_MYSTERY_AVATAR_SRC = '/auction_module/static/img/default_icon.png';

  function acMysteryEnsureGenericAvatar() {
    var wrap = acMysteryPhotoWrap();
    if (!wrap) return;
    if (window.getComputedStyle(wrap).position === 'static') {
      wrap.style.position = 'relative';
    }
    var avatar = wrap.querySelector('.ac-mystery-generic-avatar');
    if (!avatar) {
      avatar = document.createElement('img');
      avatar.className = 'ac-mystery-generic-avatar';
      avatar.alt = 'Mystery Player';
      avatar.src = AC_MYSTERY_AVATAR_SRC;
      wrap.insertBefore(avatar, wrap.firstChild);
    } else if (avatar.getAttribute('src') !== AC_MYSTERY_AVATAR_SRC) {
      avatar.src = AC_MYSTERY_AVATAR_SRC;
    }
  }

  function acMysteryRemoveGenericAvatar() {
    var avatars = document.querySelectorAll('.ac-mystery-generic-avatar');
    for (var i = 0; i < avatars.length; i++) {
      if (avatars[i].parentNode) avatars[i].parentNode.removeChild(avatars[i]);
    }
  }

  function acMysteryShowSoldStamp(info) {
    acMysteryRemoveSoldStamp();
    if (!info) return;
    var wrap = acMysteryPhotoWrap();
    if (!wrap) return;
    if (window.getComputedStyle(wrap).position === 'static') {
      wrap.style.position = 'relative';
    }
    var stamp = document.createElement('div');
    stamp.className = 'ac-mystery-sold-stamp';
    var team = info.team_name || 'Team';
    var pts = info.final_point != null ? info.final_point : '';
    stamp.innerHTML =
      '<span class="ac-mss-label">SOLD</span>' +
      '<span class="ac-mss-team">to ' + String(team).replace(/</g, '&lt;') + '</span>' +
      (pts !== '' ? '<span class="ac-mss-pts">for ' + pts + ' pts</span>' : '');
    wrap.appendChild(stamp);
  }

  window.acMysteryUpdateControls = function () {
    var revealBtn = document.getElementById('acMysteryRevealBtn');
    var isMystery = !!window.AUCTION_IS_MYSTERY;
    var revealed = !!window.AUCTION_MYSTERY_REVEALED;
    var awaiting = !!window.AUCTION_MYSTERY_AWAITING_REVEAL;

    if (revealBtn) {
      if (revealBtn.parentNode !== document.body) document.body.appendChild(revealBtn);
      if (isMystery && !revealed && awaiting) revealBtn.classList.add('is-visible');
      else revealBtn.classList.remove('is-visible');
    }

    if (isMystery && (awaiting || revealed) && window.AUCTION_MYSTERY_SOLD_INFO) {
      acMysteryHideActionButtons();
    }

    var nextBtns = acMysteryNextButtons();
    for (var i = 0; i < nextBtns.length; i++) {
      if (isMystery && awaiting && !revealed) {
        nextBtns[i].classList.add('mystery-locked');
        nextBtns[i].setAttribute('disabled', 'disabled');
      } else {
        nextBtns[i].classList.remove('mystery-locked');
        nextBtns[i].removeAttribute('disabled');
      }
    }
  };

  window.acMysteryApplyMask = function () {
    window.AUCTION_IS_MYSTERY = acMysteryFlag();
    if (window.AUCTION_IS_MYSTERY && !window.AUCTION_MYSTERY_REVEALED) {
      document.body.removeAttribute('data-mystery-revealed');
      acMysteryEnsureGenericAvatar();
    } else if (!window.AUCTION_IS_MYSTERY) {
      acMysteryRemoveGenericAvatar();
    }
    acMysteryUpdateControls();
  };

  /** Apply mystery UI from attributes already on <body> (set by changeImage / sell modal).
   *  Do NOT re-fetch the page here — that races with acCommitPlayerOnStage and can
   *  briefly read the previous on-stage player, clearing data-is-mystery and revealing
   *  a mystery player's identity on display_auction.
   */
  window.acMysteryApplyFromBody = function () {
    window.AUCTION_IS_MYSTERY = acMysteryFlag();
    window.AUCTION_MYSTERY_AWAITING_REVEAL = false;
    window.AUCTION_MYSTERY_SOLD_INFO = null;
    acMysterySetRevealed(false);
    acMysteryRemoveSoldStamp();
    acMysteryRemoveGenericAvatar();
    acMysteryShowActionButtons();
    if (window.AUCTION_IS_MYSTERY) acMysteryEnsureGenericAvatar();
    acMysteryUpdateControls();
  };

  window.acRevealMysteryPlayer = function () {
    if (!window.AUCTION_IS_MYSTERY) return;
    var playerId = parseInt(document.body.getAttribute('data-player-id') || '0', 10);
    if (playerId) {
      // display_auction is auth=none — use db-explicit console_call (sudo whitelist)
      // instead of /web/dataset/call_kw so the live board sees mystery_revealed.
      var parts = (window.location.pathname || '').split('/').filter(Boolean);
      var dbName = parts.length ? parts[0] : '';
      var payload = {
        jsonrpc: '2.0', method: 'call', id: Date.now(),
        params: {
          model: 'auction.team.player',
          method: 'action_reveal_mystery',
          args: [playerId],
          kwargs: {}
        }
      };
      var url = dbName
        ? ('/' + dbName + '/auction/console_call')
        : '/web/dataset/call_kw';
      fetch(url, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(payload)
      }).catch(function () { /* UI reveal still proceeds locally */ });
    }
    acMysterySetRevealed(true);
    window.AUCTION_MYSTERY_AWAITING_REVEAL = false;
    acMysteryRemoveGenericAvatar();
    acMysteryHideActionButtons();
    acMysteryShowSoldStamp(window.AUCTION_MYSTERY_SOLD_INFO);
    acMysteryUpdateControls();
  };

  window.acMysteryMarkSold = function (soldInfo) {
    window.AUCTION_IS_MYSTERY = acMysteryFlag() || !!window.AUCTION_IS_MYSTERY;
    if (!window.AUCTION_IS_MYSTERY || window.AUCTION_MYSTERY_REVEALED) return false;
    if (soldInfo) {
      window.AUCTION_MYSTERY_SOLD_INFO = {
        team_id: soldInfo.team_id,
        team_name: soldInfo.team_name,
        final_point: soldInfo.final_point
      };
    }
    window.AUCTION_MYSTERY_AWAITING_REVEAL = true;
    acMysterySetRevealed(false);
    acMysteryEnsureGenericAvatar();
    acMysteryHideActionButtons();
    acMysteryUpdateControls();
    return true;
  };

  window.acMysterySyncFromZone = function () {
    // Caller already copied data-is-mystery / data-player-id from the prefetch HTML.
    window.acMysteryApplyFromBody();
  };

  async function acMysteryRefreshFlagFromServer() {
    // Legacy helper — prefer acMysteryApplyFromBody after a zone swap.
    // If used, still avoid trusting a stale on-stage player when possible.
    try {
      var url = window.location.href.split('?')[0];
      var r = await fetch(url, { cache: 'no-store' });
      if (!r.ok) throw new Error('HTTP ' + r.status);
      var html = await r.text();
      var doc = new DOMParser().parseFromString(html, 'text/html');
      var flag = (doc.body && doc.body.getAttribute('data-is-mystery')) || '0';
      var newId = doc.body && doc.body.getAttribute('data-player-id');
      var curId = document.body.getAttribute('data-player-id');
      // Only adopt server flags when the stage player matches who we are showing.
      if (newId && curId && String(newId) === String(curId)) {
        document.body.setAttribute('data-is-mystery', flag);
      }
      window.acMysteryApplyFromBody();
    } catch (e) {
      window.acMysteryApplyFromBody();
    }
  }

  function acMysteryWrapChangeImage() {
    if (typeof window.changeImage !== 'function' || window.changeImage._mysteryWrapped) return;
    var original = window.changeImage;
    window.changeImage = async function (skipOverlay) {
      if (window.AUCTION_IS_MYSTERY && window.AUCTION_MYSTERY_AWAITING_REVEAL && !window.AUCTION_MYSTERY_REVEALED) {
        return;
      }
      var zone = document.querySelector('[data-player-zone]');
      // Hide stage during swap so the next identity never flashes unmasked
      if (zone) zone.style.visibility = 'hidden';
      try {
        var result = await original.apply(this, arguments);
        // Mask from body attrs set by the theme swap — never re-fetch here
        // (re-fetch raced with stage commit and cleared mystery masking).
        window.acMysteryApplyFromBody();
        return result;
      } finally {
        if (zone) zone.style.visibility = '';
      }
    };
    window.changeImage._mysteryWrapped = true;
  }

  function acMysteryBoot() {
    window.AUCTION_IS_MYSTERY = acMysteryFlag();
    window.AUCTION_MYSTERY_AWAITING_REVEAL = false;
    window.AUCTION_MYSTERY_SOLD_INFO = null;
    acMysterySetRevealed(false);
    var revealBtn = document.getElementById('acMysteryRevealBtn');
    if (revealBtn && revealBtn.parentNode !== document.body) {
      document.body.appendChild(revealBtn);
    }
    if (window.AUCTION_IS_MYSTERY) acMysteryEnsureGenericAvatar();
    acMysteryUpdateControls();
    acMysteryWrapChangeImage();
    setTimeout(acMysteryWrapChangeImage, 0);
    setTimeout(acMysteryWrapChangeImage, 250);
  }

  // Apply mystery flag as early as possible (script may run before body exists
  // if included late; boot handles the normal path).
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', acMysteryBoot);
  } else {
    acMysteryBoot();
  }
})();
//
